<style>/* ==========================================================================
   EIG Day 2 On-Demand — scoped stylesheet
   Every rule lives under .eigod so it can sit inside any WordPress theme
   without leaking out or being overridden by generic element styles.
   ========================================================================== */

.eigod {
  --bg: #050a15;
  --bg-2: #08111f;
  --bg-3: #0c182c;
  --panel: rgba(255, 255, 255, .032);
  --panel-2: rgba(255, 255, 255, .055);
  --line: rgba(222, 230, 245, .09);
  --line-2: rgba(222, 230, 245, .16);
  --copper: #c98552;
  --copper-hi: #e8b38a;
  --copper-lo: #8e4e28;
  --copper-line: rgba(232, 179, 138, .34);
  --copper-grad: linear-gradient(135deg, #f3cba6 0%, #d99665 38%, #b46a3a 70%, #8e4e28 100%);
  --ink: #eef2f8;
  --ink-2: #b9c3d5;
  --muted: #7f8ca4;
  --serif: 'Instrument Serif', 'Times New Roman', serif;
  --sans: 'Inter Tight', 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --radius: 18px;
  --wrap: 1240px;
  --gutter: clamp(20px, 4vw, 44px);
  --ease: cubic-bezier(.2, .7, .1, 1);

  position: relative;
  background: var(--bg);
  color: var(--ink-2);
  font-family: var(--sans);
  font-size: 17px;
  line-height: 1.6;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  overflow-x: clip;
}
.eigod *, .eigod *::before, .eigod *::after { box-sizing: border-box; }
/* Defensive reset: beats generic theme rules (h2 { … }, .entry-content p { … }) but loses to our own
   component classes, so the page renders the same inside any WordPress theme. */
.eigod :is(h1, h2, h3, h4, h5, h6, p, ul, ol, li, figure, figcaption, blockquote, dl, dd, details, summary, small, em, b, strong, span) {
  margin: 0; padding: 0; border: 0; background: none; box-shadow: none; text-transform: none; text-decoration: none;
  letter-spacing: normal; font-family: inherit; font-size: inherit; font-weight: inherit; line-height: inherit; color: inherit; text-align: inherit; text-shadow: none;
}
.eigod :is(b, strong) { font-weight: 600; }
/* structural elements: keep the type chain flowing from .eigod even if a theme styles bare div/a/nav */
.eigod :is(div, section, header, footer, nav, main, article, aside, a, button, label, i, time, abbr) { font-family: inherit; line-height: inherit; letter-spacing: inherit; text-transform: none; }
.eigod :is(ul, ol, li) { list-style: none; }
.eigod :is(img, picture, video, svg) { display: block; max-width: 100%; border: 0; padding: 0; margin: 0; box-shadow: none; background: none; border-radius: 0; }
.eigod :is(a) { color: inherit; text-decoration: none; border: 0; box-shadow: none; background: none; text-transform: none; }
.eigod :is(button, input) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; border-radius: 0; box-shadow: none; text-transform: none; letter-spacing: inherit; cursor: pointer; min-height: 0; min-width: 0; height: auto; width: auto; line-height: inherit; white-space: normal; text-align: inherit; text-shadow: none; outline-offset: 0; }
.eigod ::selection { background: rgba(201, 133, 82, .35); color: #fff; }
.eigod :focus-visible { outline: 2px solid var(--copper-hi); outline-offset: 3px; border-radius: 6px; }

.eigod .eo-wrap { width: 100%; max-width: var(--wrap); margin: 0 auto; padding: 0 var(--gutter); }
.eigod .eo-section { position: relative; padding: clamp(84px, 11vw, 168px) 0; }
.eigod [hidden] { display: none !important; }
