.eigod .eo-features { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.eigod .eo-feature {
  position: relative; padding: 30px 26px 30px; border-radius: var(--radius); background: var(--panel); border: 1px solid var(--line);
  display: flex; flex-direction: column; gap: 14px; overflow: hidden; transition: border-color .4s, background-color .4s, transform .6s var(--ease);
}
.eigod .eo-feature::before { content: ''; position: absolute; left: 26px; right: 26px; top: 0; height: 1px; background: var(--copper-grad); opacity: .0; transition: opacity .5s; }
.eigod .eo-feature:hover { border-color: var(--line-2); background: var(--panel-2); transform: translateY(-4px); }
.eigod .eo-feature:hover::before { opacity: .9; }
.eigod .eo-feature-ico { width: 44px; height: 44px; border-radius: 12px; display: grid; place-items: center; color: var(--copper-hi); background: rgba(232, 179, 138, .07); border: 1px solid rgba(232, 179, 138, .18); }
.eigod .eo-feature-ico svg { width: 22px; height: 22px; }
.eigod .eo-feature h3 { font-family: var(--sans); font-size: 18px; font-weight: 600; color: var(--ink); letter-spacing: -.005em; margin-top: 10px; }
.eigod .eo-feature p { font-size: 15px; line-height: 1.6; color: var(--ink-2); }

/* ---------- programme ---------- */
.eigod .eo-programme { display: flex; flex-direction: column; gap: clamp(56px, 7vw, 96px); }
.eigod .eo-block-head { display: flex; align-items: baseline; justify-content: space-between; gap: 20px; padding-bottom: 22px; border-bottom: 1px solid var(--line-2); }
.eigod .eo-block-head h3 { display: flex; align-items: baseline; gap: 18px; flex-wrap: wrap; }
.eigod .eo-block-head h3 small { font-family: var(--sans); font-size: 12px; letter-spacing: .22em; text-transform: uppercase; color: var(--copper-hi); font-weight: 600; }
.eigod .eo-block-head > span { font-size: 13.5px; color: var(--muted); white-space: nowrap; }
.eigod .eo-talk { border-bottom: 1px solid var(--line); }
.eigod .eo-talk-row {
  width: 100%; display: grid; grid-template-columns: 96px minmax(0, 1fr) auto 28px; align-items: center; gap: 28px;
  padding: 30px 6px; text-align: left; position: relative; transition: background-color .3s;
}
.eigod .eo-talk-row::before { content: ''; position: absolute; inset: 0 -18px; border-radius: 14px; background: var(--panel); opacity: 0; transition: opacity .35s; z-index: -1; }
.eigod .eo-talk { position: relative; isolation: isolate; }
.eigod .eo-talk-row:hover::before, .eigod .eo-talk.is-open .eo-talk-row::before { opacity: 1; }
.eigod .eo-talk-time { font-size: 13.5px; color: var(--muted); font-variant-numeric: tabular-nums; letter-spacing: .02em; }
.eigod .eo-talk-main { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.eigod .eo-talk-tags { display: flex; gap: 8px; flex-wrap: wrap; }
.eigod .eo-tag { display: inline-flex; align-items: center; height: 24px; padding: 0 10px; border-radius: 999px; font-size: 11px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--copper-hi); border: 1px solid rgba(232, 179, 138, .28); background: rgba(232, 179, 138, .05); }
.eigod .eo-tag.is-quiet { color: var(--muted); border-color: var(--line-2); background: transparent; }
.eigod .eo-talk-title { font-family: var(--serif); font-weight: 400; color: var(--ink); font-size: clamp(24px, 2.4vw, 32px); line-height: 1.12; letter-spacing: -.008em; }
.eigod .eo-people { display: flex; align-items: center; gap: 14px; min-width: 0; }
.eigod .eo-avs { display: flex; flex: none; }
.eigod .eo-avs img { width: 32px; height: 32px; border-radius: 50%; object-fit: cover; border: 2px solid var(--bg); margin-left: -9px; filter: grayscale(.4) contrast(1.05); }
.eigod .eo-avs img:first-child { margin-left: 0; }
.eigod .eo-people-names { font-size: 14.5px; color: var(--ink-2); line-height: 1.4; }
.eigod .eo-people-names em { font-style: normal; color: var(--muted); }
.eigod .eo-talk-dur { font-size: 14px; color: var(--ink-2); font-variant-numeric: tabular-nums; white-space: nowrap; }
.eigod .eo-chev { width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--line-2); display: grid; place-items: center; color: var(--ink-2); transition: transform .5s var(--ease), border-color .3s, color .3s; }
.eigod .eo-chev svg { width: 12px; height: 12px; }
.eigod .eo-talk.is-open .eo-chev { transform: rotate(45deg); border-color: var(--copper-line); color: var(--copper-hi); }
.eigod .eo-talk-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .6s var(--ease); }
.eigod .eo-talk.is-open .eo-talk-body { grid-template-rows: 1fr; }
.eigod .eo-talk-body > div { overflow: hidden; }
.eigod .eo-talk-detail { display: grid; grid-template-columns: 96px minmax(0, 1fr) minmax(0, .62fr); gap: 28px; padding: 0 6px 34px; }
.eigod .eo-talk-detail p { color: var(--ink-2); font-size: 16px; max-width: 38em; }
.eigod .eo-talk-detail ul { display: flex; flex-direction: column; gap: 10px; font-size: 14.5px; }
.eigod .eo-talk-detail li { display: flex; gap: 10px; }
.eigod .eo-talk-detail li::before { content: ''; flex: none; width: 6px; height: 6px; margin-top: 9px; border-radius: 50%; background: var(--copper); }
.eigod .eo-talk-aside { display: flex; flex-direction: column; gap: 16px; align-items: flex-start; }
.eigod .eo-roles { font-size: 13.5px; color: var(--muted); line-height: 1.55; }
.eigod .eo-roles b { color: var(--ink-2); font-weight: 500; }

/* ---------- speakers ---------- */
.eigod .eo-spk-group + .eo-spk-group { margin-top: 64px; padding-top: 40px; border-top: 1px solid var(--line, rgba(255, 255, 255, .08)); }
.eigod .eo-spk-label { display: flex; align-items: baseline; gap: 12px; margin-bottom: 26px; font-size: 12px; font-weight: 600; letter-spacing: .26em; text-transform: uppercase; color: var(--copper-hi); }
.eigod .eo-spk-label span { color: var(--muted); letter-spacing: .1em; font-weight: 500; }
.eigod .eo-speaker-ph.is-mono { display: grid; place-items: center; background: radial-gradient(120% 120% at 30% 20%, rgba(232, 179, 138, .22), rgba(12, 24, 44, .9) 70%), var(--bg-3); }
.eigod .eo-speaker-ph.is-mono::after { display: none; }
.eigod .eo-speaker-ph.is-mono span { font-family: var(--serif); font-size: clamp(30px, 3.4vw, 48px); line-height: 1; color: var(--copper-hi); letter-spacing: .02em; }
.eigod .eo-speakers { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 28px 18px; }
.eigod .eo-speaker { display: flex; flex-direction: column; gap: 14px; }
.eigod .eo-speaker-ph { position: relative; aspect-ratio: 1; border-radius: 16px; overflow: hidden; background: var(--bg-3); }
.eigod .eo-speaker-ph img { width: 100%; height: 100%; object-fit: cover; filter: grayscale(1) contrast(1.08) brightness(.88); transform: scale(1.02); transition: filter .7s var(--ease), transform .9s var(--ease); }
.eigod .eo-speaker-ph::after { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(12, 24, 44, 0) 35%, rgba(12, 24, 44, .55) 100%), linear-gradient(135deg, rgba(201, 133, 82, .18), rgba(8, 17, 31, .35)); mix-blend-mode: multiply; transition: opacity .7s var(--ease); }
.eigod .eo-speaker:hover .eo-speaker-ph img { filter: grayscale(0) contrast(1) brightness(1); transform: scale(1.06); }
.eigod .eo-speaker:hover .eo-speaker-ph::after { opacity: .25; }
.eigod .eo-speaker-ph::before { content: ''; position: absolute; inset: 0; z-index: 1; border-radius: 16px; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .07); pointer-events: none; }
.eigod .eo-speaker b { display: block; color: var(--ink); font-weight: 600; font-size: 15px; letter-spacing: -.003em; }
.eigod .eo-speaker span { display: block; color: var(--muted); font-size: 13px; line-height: 1.4; margin-top: 3px; }

/* ---------- pricing ---------- */
.eigod .eo-pricing { overflow: hidden; }
.eigod .eo-pricing::before { content: ''; position: absolute; left: 50%; top: 0; width: min(1100px, 120vw); height: 70%; transform: translateX(-50%); background: radial-gradient(closest-side, rgba(201, 133, 82, .16), transparent 75%); pointer-events: none; }
.eigod .eo-price-grid { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 480px); gap: clamp(40px, 7vw, 110px); align-items: center; }
.eigod .eo-price-copy { display: flex; flex-direction: column; gap: 26px; }
.eigod .eo-checks { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 28px; margin-top: 8px; }
.eigod .eo-checks li { display: flex; gap: 12px; font-size: 15.5px; color: var(--ink-2); line-height: 1.45; }
.eigod .eo-checks svg { flex: none; width: 18px; height: 18px; margin-top: 2px; color: var(--copper-hi); }
.eigod .eo-card {
  position: relative; border-radius: 26px; padding: 1px;
  background: linear-gradient(160deg, rgba(243, 203, 166, .7), rgba(255, 255, 255, .08) 32%, rgba(255, 255, 255, .04) 68%, rgba(201, 133, 82, .55));
  box-shadow: 0 50px 140px -50px rgba(0, 0, 0, .95), 0 0 80px -30px rgba(201, 133, 82, .35);
}
.eigod .eo-card-in { position: relative; border-radius: 25px; overflow: hidden; padding: clamp(30px, 3.4vw, 44px); background: linear-gradient(180deg, rgba(14, 26, 47, .94), rgba(7, 13, 25, .97)); }
.eigod .eo-card-in::before { content: ''; position: absolute; inset: 0; background: url('data:image/webp;base64,') center/cover; opacity: .14; mix-blend-mode: screen; pointer-events: none; }
.eigod .eo-card-in > * { position: relative; }
.eigod .eo-card-top { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.eigod .eo-card-top img { width: 40px; }
.eigod .eo-card-name { font-family: var(--serif); color: var(--ink); font-size: 30px; line-height: 1.05; margin-top: 26px; }
.eigod .eo-card-sub { color: var(--muted); font-size: 14.5px; margin-top: 8px; }
.eigod .eo-price { display: flex; align-items: flex-start; gap: 6px; margin: 30px 0 4px; color: var(--ink); }
.eigod .eo-price sup { font-family: var(--serif); font-size: 34px; line-height: 1; margin-top: 12px; color: var(--copper-hi); }
.eigod .eo-price b { font-family: var(--serif); font-weight: 400; font-size: clamp(88px, 9vw, 116px); line-height: .9; letter-spacing: -.03em; font-variant-numeric: lining-nums; }
.eigod .eo-price-note { font-size: 13.5px; color: var(--muted); letter-spacing: .02em; }
.eigod .eo-card-list { display: flex; flex-direction: column; gap: 12px; margin: 28px 0 30px; padding-top: 26px; border-top: 1px solid var(--line); }
.eigod .eo-card-list li { display: flex; gap: 12px; font-size: 15px; color: var(--ink-2); }
.eigod .eo-card-list svg { flex: none; width: 17px; height: 17px; margin-top: 3px; color: var(--copper-hi); }
.eigod .eo-card .eo-btn { width: 100%; }
.eigod .eo-secure { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 16px; font-size: 12.5px; color: var(--muted); }
.eigod .eo-secure svg { width: 13px; height: 13px; }
.eigod .eo-team { margin-top: 22px; padding-top: 20px; border-top: 1px solid var(--line); font-size: 13.5px; color: var(--muted); text-align: center; }
.eigod .eo-team a { color: var(--copper-hi); }

/* ---------- FAQ ---------- */
.eigod .eo-faq-grid { display: grid; grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); gap: clamp(40px, 7vw, 110px); }
.eigod .eo-faq { border-top: 1px solid var(--line-2); }
.eigod .eo-faq details { border-bottom: 1px solid var(--line); }
.eigod .eo-faq summary { list-style: none; cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 26px 0; color: var(--ink); font-size: 18.5px; font-weight: 500; letter-spacing: -.005em; }
.eigod .eo-faq summary::-webkit-details-marker { display: none; }
.eigod .eo-faq summary i { position: relative; flex: none; width: 14px; height: 14px; }
.eigod .eo-faq summary i::before, .eigod .eo-faq summary i::after { content: ''; position: absolute; left: 0; right: 0; top: 50%; height: 1.5px; margin-top: -.75px; background: var(--copper-hi); transition: transform .45s var(--ease); }
.eigod .eo-faq summary i::after { transform: rotate(90deg); }
.eigod .eo-faq details[open] summary i::after { transform: rotate(0); }
.eigod .eo-faq details p { padding: 0 48px 28px 0; color: var(--ink-2); font-size: 16px; max-width: 42em; }
.eigod .eo-faq details p a { color: var(--copper-hi); }

/* ---------- final CTA ---------- */
.eigod .eo-final { position: relative; isolation: isolate; overflow: hidden; text-align: center; padding: clamp(120px, 15vw, 220px) 0 clamp(110px, 13vw, 190px); }
.eigod .eo-final-bg { position: absolute; inset: 0; z-index: -2; }
.eigod .eo-final-bg img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 62%; }
.eigod .eo-final::before { content: ''; position: absolute; inset: 0; z-index: -1; background: radial-gradient(48% 46% at 50% 48%, rgba(5, 10, 21, .78), rgba(5, 10, 21, 0) 100%), linear-gradient(180deg, var(--bg) 0%, rgba(5, 10, 21, .55) 30%, rgba(5, 10, 21, .45) 60%, rgba(5, 10, 21, .92) 100%); }
@media (max-width: 720px) { .eigod .eo-final::before { background: radial-gradient(90% 40% at 50% 50%, rgba(5, 10, 21, .85), rgba(5, 10, 21, 0) 100%), linear-gradient(180deg, var(--bg) 0%, rgba(5, 10, 21, .6) 30%, rgba(5, 10, 21, .55) 60%, rgba(5, 10, 21, .94) 100%); } }
.eigod .eo-final-in { display: flex; flex-direction: column; align-items: center; gap: 30px; }
.eigod .eo-final .eo-h2 { max-width: 13em; }
.eigod .eo-final p { max-width: 34em; color: var(--ink-2); }

/* ---------- footer ---------- */
.eigod .eo-foot { border-top: 1px solid var(--line); padding: 54px 0 46px; }
.eigod .eo-foot-in { display: flex; justify-content: space-between; align-items: center; gap: 30px; flex-wrap: wrap; }
.eigod .eo-foot img { height: 40px; width: auto; opacity: .92; }
.eigod .eo-foot nav { display: flex; gap: 28px; flex-wrap: wrap; font-size: 14px; }
.eigod .eo-foot nav a:hover { color: var(--ink); }
.eigod .eo-foot small { display: block; width: 100%; margin-top: 30px; padding-top: 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12.5px; }

/* ---------- reveal ---------- */
.eigod.eo-js [data-reveal] { opacity: 0; transform: translate3d(0, 22px, 0); transition: opacity 1s var(--ease), transform 1.1s var(--ease); transition-delay: var(--d, 0s); }
.eigod.eo-js [data-reveal].is-in { opacity: 1; transform: none; }
.eigod .eo-draw { transform: scaleX(0); transform-origin: left; transition: transform 1.6s var(--ease) .2s; }
.eigod .eo-draw.is-in { transform: scaleX(1); }
@media (prefers-reduced-motion: reduce) {
  .eigod *, .eigod *::before, .eigod *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
  .eigod.eo-js [data-reveal] { opacity: 1; transform: none; }
  .eigod .eo-draw { transform: none; }
  .eigod .eo-hero-bg img { transform: scale(1.04); }
}

/* ==========================================================================
   Watch page
   ========================================================================== */
.eigod .eo-watch-top { position: sticky; top: 0; z-index: 50; background: rgba(5, 10, 21, .8); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); border-bottom: 1px solid var(--line); }
.eigod .eo-watch-top .eo-nav-in { height: 68px; }
.eigod .eo-watch-top .eo-link { font-size: 14.5px; }
.eigod .eo-badge { display: inline-flex; align-items: center; gap: 8px; height: 30px; padding: 0 12px; border-radius: 999px; font-size: 12px; font-weight: 600; letter-spacing: .06em; color: var(--copper-hi); border: 1px solid rgba(232, 179, 138, .3); background: rgba(232, 179, 138, .06); }
.eigod .eo-badge::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: var(--copper-hi); box-shadow: 0 0 10px var(--copper-hi); }
.eigod .eo-watch { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 36px; padding-top: 30px; padding-bottom: 100px; align-items: start; }
.eigod .eo-stage { display: flex; flex-direction: column; gap: 28px; min-width: 0; }
.eigod .eo-now { display: flex; flex-direction: column; gap: 18px; }
.eigod .eo-now-meta { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 13.5px; color: var(--muted); }
.eigod .eo-now h1 { font-family: var(--serif); font-weight: 400; color: var(--ink); font-size: clamp(30px, 3.4vw, 46px); line-height: 1.06; letter-spacing: -.012em; }
.eigod .eo-now-cols { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: 36px; padding-top: 26px; border-top: 1px solid var(--line); }
.eigod .eo-now-cols h2 { font-size: 12px; letter-spacing: .2em; text-transform: uppercase; color: var(--copper-hi); font-weight: 600; margin-bottom: 14px; }
.eigod .eo-now-cols p { color: var(--ink-2); font-size: 16px; }
.eigod .eo-chapters { display: flex; flex-direction: column; }
.eigod .eo-chapters button { display: grid; grid-template-columns: 62px minmax(0, 1fr); gap: 12px; align-items: baseline; text-align: left; padding: 10px 10px; margin: 0 -10px; border-radius: 10px; font-size: 15px; color: var(--ink-2); transition: background-color .25s, color .25s; }
.eigod .eo-chapters button:hover, .eigod .eo-chapters button.is-on { background: var(--panel-2); color: var(--ink); }
.eigod .eo-chapters button span { font-size: 13px; color: var(--copper-hi); font-variant-numeric: tabular-nums; }
.eigod .eo-empty { font-size: 14.5px; color: var(--muted); }
.eigod .eo-speaker-list { display: flex; flex-direction: column; gap: 14px; margin-top: 20px; }
.eigod .eo-speaker-list li { display: flex; gap: 12px; align-items: center; }
.eigod .eo-speaker-list img { width: 40px; height: 40px; border-radius: 50%; object-fit: cover; filter: grayscale(.3); }
.eigod .eo-speaker-list b { display: block; color: var(--ink); font-weight: 600; font-size: 14.5px; }
.eigod .eo-speaker-list span { display: block; color: var(--muted); font-size: 13px; }

.eigod .eo-list { position: sticky; top: 98px; border-radius: var(--radius); background: var(--panel); border: 1px solid var(--line); overflow: hidden; }
.eigod .eo-list-head { display: flex; justify-content: space-between; align-items: baseline; padding: 20px 22px 16px; border-bottom: 1px solid var(--line); }
.eigod .eo-list-head b { font-family: var(--serif); font-weight: 400; color: var(--ink); font-size: 22px; }
.eigod .eo-list-head span { font-size: 12.5px; color: var(--muted); }
.eigod .eo-list-scroll { max-height: calc(100vh - 200px); overflow: auto; padding: 8px; scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, .15) transparent; }
.eigod .eo-list-group { padding: 14px 12px 6px; font-size: 11px; letter-spacing: .2em; text-transform: uppercase; color: var(--muted); font-weight: 600; }
.eigod .eo-item { width: 100%; display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 12px; align-items: start; text-align: left; padding: 12px; border-radius: 12px; transition: background-color .25s; }
.eigod .eo-item:hover { background: var(--panel-2); }
.eigod .eo-item.is-on { background: rgba(232, 179, 138, .08); box-shadow: inset 0 0 0 1px rgba(232, 179, 138, .22); }
.eigod .eo-item-n { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; padding-top: 2px; }
.eigod .eo-item.is-on .eo-item-n { color: var(--copper-hi); }
.eigod .eo-item-t { display: block; color: var(--ink); font-size: 14.5px; font-weight: 500; line-height: 1.35; }
.eigod .eo-item-s { display: block; color: var(--muted); font-size: 12.5px; margin-top: 4px; }
.eigod .eo-item-bar { display: block; height: 2px; margin-top: 10px; border-radius: 2px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.eigod .eo-item-bar i { display: block; height: 100%; width: 0; background: var(--copper-grad); }

/* ---------- player ---------- */
.eigod .eo-player { position: relative; border-radius: 18px; overflow: hidden; background: #000; aspect-ratio: 16 / 9; box-shadow: 0 40px 100px -40px rgba(0, 0, 0, .95), 0 0 0 1px var(--line); user-select: none; -webkit-user-select: none; }
.eigod .eo-player video { width: 100%; height: 100%; object-fit: contain; background: #000; }
.eigod .eo-player:fullscreen { border-radius: 0; aspect-ratio: auto; }
.eigod .eo-player .eo-poster { z-index: 3; }
.eigod .eo-player.is-ready .eo-poster.is-soon { display: none; }
.eigod .eo-p-big { position: absolute; inset: 0; z-index: 2; display: grid; place-items: center; opacity: 1; transition: opacity .35s; }
.eigod .eo-player.is-playing .eo-p-big { opacity: 0; pointer-events: none; }
.eigod .eo-p-chrome {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 4; padding: 40px 18px 14px;
